{
  "version": 1,
  "purpose": "Prospective synthetic native invoice comparison; no live provider effects.",
  "frozen_before_inference": true,
  "model": "qwen2.5:7b",
  "conditions": [
    "baseline",
    "inventory"
  ],
  "schedule": [
    {
      "case": "harbor",
      "order": [
        "baseline",
        "inventory"
      ]
    },
    {
      "case": "seiwa",
      "order": [
        "inventory",
        "baseline"
      ]
    },
    {
      "case": "linden",
      "order": [
        "baseline",
        "inventory"
      ]
    },
    {
      "case": "ardent",
      "order": [
        "inventory",
        "baseline"
      ]
    },
    {
      "case": "rolls",
      "order": [
        "baseline",
        "inventory"
      ]
    }
  ],
  "decision": "Retain every first original outcome, including timeout and invalid output. Compare complete grounded invoices and full elapsed cost, recording cold load without subtracting it. Required slots alone are not success. Lost or invented charges, changed recipients/payments/terms, or a completed baseline becoming a failed proposal prevent shipping. Do not tune on these cases and call them unseen again.",
  "calibration": {
    "id": "calibration",
    "source": "Bill to: Calibration Studio <billing@calibration.example>\nOne poster design at EUR 40.\nNet 14.\n",
    "expected": {
      "client_name": "Calibration Studio",
      "client_email": "billing@calibration.example",
      "currency": "EUR",
      "due_days": 14,
      "amount_paid": "0",
      "total": "40",
      "items": [
        {
          "description_any": [
            "poster"
          ],
          "qty": "1",
          "unit_price": "40",
          "unit_allowed": [
            null,
            "poster",
            "posters",
            "design"
          ]
        }
      ]
    }
  },
  "cases": [
    {
      "id": "harbor",
      "source": "From: Mara <mara@harbor.example>\nBill to: Harbor House <finance@harbor.example>\nPlease invoice the completed work: three recorded conversations at GBP 90 per conversation.\nFour hours of audio cleanup were agreed at GBP 28 per hour.\nPlease also include the agreed flat courier fee of GBP 22.\nThe agreed invoice total is GBP 404.\nNet 14.\n",
      "expected": {
        "client_name": "Harbor House",
        "client_email": "finance@harbor.example",
        "currency": "GBP",
        "due_days": 14,
        "amount_paid": "0",
        "total": "404",
        "items": [
          {
            "description_any": [
              "conversation",
              "interview"
            ],
            "qty": "3",
            "unit_price": "90",
            "unit_allowed": [
              null,
              "conversation",
              "conversations",
              "interview",
              "interviews"
            ]
          },
          {
            "description_any": [
              "cleanup",
              "clean-up",
              "clean up"
            ],
            "qty": "4",
            "unit_price": "28",
            "unit_allowed": [
              "hour",
              "hours",
              "hr",
              "hrs"
            ]
          },
          {
            "description_any": [
              "courier"
            ],
            "qty": "1",
            "unit_price": "22",
            "unit_allowed": [
              null,
              "fee",
              "courier",
              "item"
            ]
          }
        ]
      }
    },
    {
      "id": "seiwa",
      "source": "From: Yui <yui@seiwa.example>\nBill to: Seiwa Museum <accounts@seiwa.example>\nWe accepted eight caption panels at JPY 2400 per panel.\nThe agreed handling fee is JPY 6500, charged once.\nPlease add the agreed return courier fee of JPY 1800, also charged once.\nWe already paid JPY 5000 toward this invoice.\nPayment is due on receipt.\n",
      "expected": {
        "client_name": "Seiwa Museum",
        "client_email": "accounts@seiwa.example",
        "currency": "JPY",
        "due_days": 0,
        "amount_paid": "5000",
        "total": "27500",
        "items": [
          {
            "description_any": [
              "caption",
              "panel"
            ],
            "qty": "8",
            "unit_price": "2400",
            "unit_allowed": [
              null,
              "panel",
              "panels"
            ]
          },
          {
            "description_any": [
              "handling"
            ],
            "qty": "1",
            "unit_price": "6500",
            "unit_allowed": [
              null,
              "fee",
              "item"
            ]
          },
          {
            "description_any": [
              "courier"
            ],
            "qty": "1",
            "unit_price": "1800",
            "unit_allowed": [
              null,
              "fee",
              "courier",
              "item"
            ]
          }
        ]
      }
    },
    {
      "id": "linden",
      "source": "From: Devon <devon@linden.example>\nBill to: Linden Lab <billing@linden.example>\nThe completed database migration has an agreed flat fee of USD 420.\nThe separate log archive fee is USD 65.\nInclude the agreed checksum verification fee of USD 35 as well.\nNet 21.\n> Earlier estimate: migration and support at USD 600.\n",
      "expected": {
        "client_name": "Linden Lab",
        "client_email": "billing@linden.example",
        "currency": "USD",
        "due_days": 21,
        "amount_paid": "0",
        "total": "520",
        "items": [
          {
            "description_any": [
              "migration"
            ],
            "qty": "1",
            "unit_price": "420",
            "unit_allowed": [
              null,
              "fee",
              "item"
            ]
          },
          {
            "description_any": [
              "archive"
            ],
            "qty": "1",
            "unit_price": "65",
            "unit_allowed": [
              null,
