            ]
          },
          {
            "description_any": [
              "checksum",
              "verification"
            ],
            "qty": "1",
            "unit_price": "35",
            "unit_allowed": [
              null,
              "fee",
              "item"
            ]
          }
        ]
      }
    },
    {
      "id": "ardent",
      "source": "From: Noor <noor@ardent.example>\nBill to: Ardent Film <accounts@ardent.example>\nInvoice four half-day recording sessions at EUR 160 per session.\nWe also agreed two hours of caption cleanup at EUR 45 per hour.\nInclude the agreed flat gear-return fee of EUR 28.\nNet 7.\n",
      "expected": {
        "client_name": "Ardent Film",
        "client_email": "accounts@ardent.example",
        "currency": "EUR",
        "due_days": 7,
        "amount_paid": "0",
        "total": "758",
        "items": [
          {
            "description_any": [
              "recording",
              "session"
            ],
            "qty": "4",
            "unit_price": "160",
            "unit_allowed": [
              null,
              "session",
              "sessions"
            ]
          },
          {
            "description_any": [
              "caption",
              "cleanup"
            ],
            "qty": "2",
            "unit_price": "45",
            "unit_allowed": [
              "hour",
              "hours",
              "hr",
              "hrs"
            ]
          },
          {
            "description_any": [
              "gear",
              "return"
            ],
            "qty": "1",
            "unit_price": "28",
            "unit_allowed": [
              null,
              "fee",
              "item"
            ]
          }
        ]
      }
    },
    {
      "id": "rolls",
      "source": "From: Morgan <morgan@rolls.example>\nBill to: Paper Room <billing@paperroom.example>\nPlease invoice twelve label rolls at CAD 12 per roll.\nWe agreed a separate flat cutter setup fee of CAD 12.\nThe agreed postage fee is CAD 8.\nWe already paid CAD 60 toward this invoice.\nNet 14.\n",
      "expected": {
        "client_name": "Paper Room",
        "client_email": "billing@paperroom.example",
        "currency": "CAD",
