              "type": [
                "number",
                "null"
              ]
            },
            "currency": {
              "type": [
                "string",
                "null"
              ]
            },
            "unit": {
              "type": [
                "string",
                "null"
              ]
            }
          },
          "required": [
            "kind",
            "desc",
            "qty",
            "currency",
            "unit"
          ],
          "additionalProperties": false
        }
      },
      "properties": {
        "client_name": {
          "type": [
            "string",
            "null"
          ]
        },
        "client_email": {
          "type": [
            "string",
            "null"
          ]
        },
        "currency": {
          "type": [
            "string",
            "null"
          ]
        },
        "due_days": {
          "type": [
            "integer",
            "null"
          ]
        },
        "due_date": {
          "type": [
            "string",
            "null"
          ]
        },
        "amount_paid": {
          "type": "number"
        },
        "confidence": {
          "type": "number",
          "minimum": 0,
          "maximum": 1
        },
        "issues": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "field": {
                "type": "string"
              },
              "severity": {
                "type": "string",
                "enum": [
                  "error",
                  "warning",
                  "info"
                ]
              },
              "message": {
                "type": "string"
              }
            },
            "required": [
              "field",
              "severity",
              "message"
            ]
          }
        },
        "source_amounts": {
          "type": "object",
          "properties": {
            "a1": {
              "$ref": "#/$defs/source_amount"
            }
          },
          "required": [
            "a1"
          ],
          "additionalProperties": false
        }
      },
      "required": [
        "client_name",
        "client_email",
        "currency",
        "due_days",
        "due_date",
        "amount_paid",
        "confidence",
        "issues",
        "source_amounts"
      ],
